when.condition:
@{
            var jwt = context.Request.Headers.GetValueOrDefault("Authorization","").AsJwt();
            var audience = jwt?.Claims.GetValueOrDefault("aud", new string[0]).FirstOrDefault();
            return audience == "https://cognitiveservices.azure.com";
        }

set-variable.value:
@{
        var jwt = context.Request.Headers.GetValueOrDefault("Authorization","").AsJwt();
        var name = jwt?.Claims.GetValueOrDefault("name", new string[0]).FirstOrDefault();
        if (!string.IsNullOrEmpty(name)) { return name; }
        var upn = jwt?.Claims.GetValueOrDefault("preferred_username", new string[0]).FirstOrDefault();
        if (!string.IsNullOrEmpty(upn)) { return upn; }
        var azp = jwt?.Claims.GetValueOrDefault("azp", new string[0]).FirstOrDefault();
        if (!string.IsNullOrEmpty(azp)) { return "service-principal:" + azp; }
        return "unknown-user";
    }

@{
        var jwt = context.Request.Headers.GetValueOrDefault("Authorization","").AsJwt();
        var role = jwt?.Claims.GetValueOrDefault("roles", new string[0]).FirstOrDefault();
        if (!string.IsNullOrEmpty(role)) { return role; }
        if (context.Subscription != null) { return context.Subscription.Name; }
        var mirid = jwt?.Claims.GetValueOrDefault("xms_mirid", new string[0]).FirstOrDefault();
        if (!string.IsNullOrEmpty(mirid)) { return "foundry-project:" + mirid.Split('/').Last(); }
        if (context.Product != null) { return context.Product.Name; }
        return "unattributed";
    }
